const dag = $workflow.staticData.dagState || {};
const version = $json.body.version;
dag.mergedStories = dag.mergedStories || [];
dag.mergedStories.push($json.body.story_id);
$workflow.staticData.dagState = dag;
const allStories = dag.totalStories || 0;
const merged = dag.mergedStories.length;
return [{ json: { allMerged: merged >= allStories, merged, total: allStories, version } }];
